    const input = screen.getByRole("textbox");
    const btn = screen.getByRole("button", { name: /add item/i });
    for (let i = 1; i <= 10; i++) {
      fireEvent.change(input, { target: { value: `Item ${i}` } });
      fireEvent.click(btn);
    }
    expect(screen.getAllByRole("listitem")).toHaveLength(10);
  });
});

