import { describe, expect, it, vi } from "vitest";
import { renderHook, waitFor, act } from "@testing-library/react";
import { useQuery } from "./useQuery";

describe("M9 - useQuery (hidden)", () => {
  it("re-runs fn when deps change", async () => {
    let count = 0;
    const fn = vi.fn(() => Promise.resolve(++count));
    const { result, rerender } = renderHook(
      ({ id }) => useQuery(() => fn(), [id]),
      { initialProps: { id: 1 } }
    );
    await waitFor(() => expect(result.current.status).toBe("success"));
    rerender({ id: 2 });
    await waitFor(() => {
      if (result.current.status === "success") expect(result.current.data).toBe(2);
    });
    expect(fn).toHaveBeenCalledTimes(2);
  });
  it("does not update state for stale async responses", async () => {
    let resolve1!: (v: number) => void;
    let resolve2!: (v: number) => void;
    const { result, rerender } = renderHook(
      ({ id }) => useQuery(
        () => id === 1 ? new Promise(r => { resolve1 = r; }) : new Promise(r => { resolve2 = r; }),
        [id]
      ),
      { initialProps: { id: 1 } }
    );
    rerender({ id: 2 });
    act(() => { resolve2(200); });
    await waitFor(() => expect(result.current.status).toBe("success"));
    act(() => { resolve1(100); }); // stale response
    await new Promise(r => setTimeout(r, 50));
    if (result.current.status === "success") expect(result.current.data).toBe(200);
  });
  it("defaults deps to [] and runs only once without deps", async () => {
    const fn = vi.fn(() => Promise.resolve("ok"));
    const { rerender } = renderHook(() => useQuery(fn));
    rerender();
    await new Promise(r => setTimeout(r, 50));
    expect(fn).toHaveBeenCalledTimes(1);
  });
});

